1	import java.math.BigDecimal;
2	import java.math.RoundingMode;
3	import java.util.List;
4	
5	/**
6	 * The MHPCO premium rules: the two scopes of premium modifier, the processing
7	 * fee, and rounding in the office's favor, applied to the base premium the
8	 * {@link PriceList} states for the insured items.
9	 *
10	 * Intermediate amounts stay exact fractions; only the final premium is rounded.
11	 */
12	public class PremiumPolicy {
13	
14	    private static final BigDecimal CURSE_SURCHARGE_RATE = new BigDecimal("0.50");
15	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = new BigDecimal("0.30");
16	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
17	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = new BigDecimal("0.10");
18	    private static final BigDecimal PROCESSING_FEE = new BigDecimal("5");
19	
20	    private final PriceList priceList = new PriceList();
21	
22	    /**
23	     * The office charges both kinds of modifier on a base premium, never on each
24	     * other: an item modifier on the affected item's own base premium, a
25	     * policy-wide modifier on the policy base premium. So the two are summed
26	     * alongside the base premium rather than compounded in sequence, and the
27	     * processing fee is added at the very end.
28	     */
29	    public int quote(List<InsuredItem> insuredItems) {
30	        BigDecimal policyBasePremium = priceList.policyBasePremium(insuredItems);
31	        BigDecimal premium = policyBasePremium
32	                .add(itemRiskSurcharges(insuredItems))
33	                .add(policyWideModifiers(policyBasePremium))
34	                .add(PROCESSING_FEE);
35	        return inOfficesFavor(premium);
36	    }
37	
38	    /**
39	     * Item-scope modifiers: each is charged on the base premium of the affected
40	     * item alone, so a modifier on one item never touches another item's share
41	     * of the policy.
42	     *
43	     * A curse and a high enchantment are separate risks, so an item carrying
44	     * both is surcharged for both: the office charges them side by side on the
45	     * same item base premium rather than letting the graver risk absorb the
46	     * other.
47	     */
48	    private BigDecimal itemRiskSurcharges(List<InsuredItem> insuredItems) {
49	        BigDecimal surcharges = BigDecimal.ZERO;
50	        for (InsuredItem insuredItem : insuredItems) {
51	            BigDecimal itemBasePremium = priceList.basePremium(insuredItem);
52	            if (insuredItem.cursed()) {
53	                surcharges = surcharges.add(itemBasePremium.multiply(CURSE_SURCHARGE_RATE));
54	            }
55	            if (isHighlyEnchanted(insuredItem)) {
56	                surcharges = surcharges
57	                        .add(itemBasePremium.multiply(HIGH_ENCHANTMENT_SURCHARGE_RATE));
58	            }
59	        }
60	        return surcharges;
61	    }
62	
63	    /** The office counts an item as highly enchanted from enchantment level 5 up. */
64	    private static boolean isHighlyEnchanted(InsuredItem insuredItem) {
65	        return insuredItem.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
66	    }
67	
68	    /**
69	     * Policy-scope modifiers: each is charged on the policy base premium, the
70	     * sum of all item base premiums. Every quote is a first insurance of the
71	     * items it covers, whatever the customer's history.
72	     */
73	    private BigDecimal policyWideModifiers(BigDecimal policyBasePremium) {
74	        return policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE);
75	    }
76	
77	    private int inOfficesFavor(BigDecimal premium) {
78	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
79	    }
80	}
