1	import java.io.IOException;
2	import java.io.InputStream;
3	import java.io.PrintStream;
4	import java.io.UncheckedIOException;
5	import java.util.ArrayList;
6	import java.util.List;
7	
8	import com.fasterxml.jackson.databind.JsonNode;
9	import com.fasterxml.jackson.databind.ObjectMapper;
10	import com.fasterxml.jackson.databind.node.ArrayNode;
11	import com.fasterxml.jackson.databind.node.ObjectNode;
12	
13	/**
14	 * Translates the JSON scenario protocol into MHPCO operations and back.
15	 * The protocol field names are binding; the premium rules live in
16	 * {@link PremiumPolicy}.
17	 */
18	public class ClaimOfficeCli {
19	
20	    private static final ObjectMapper JSON = new ObjectMapper();
21	
22	    private final PremiumPolicy premiumPolicy = new PremiumPolicy();
23	
24	    public void run(InputStream scenario, PrintStream results) {
25	        try {
26	            JsonNode input = JSON.readTree(scenario);
27	            ObjectNode output = JSON.createObjectNode();
28	            ArrayNode resultsNode = output.putArray("results");
29	            for (JsonNode step : input.get("steps")) {
30	                resultsNode.addObject().put("premium", premiumPolicy.quote(insuredItems(step)));
31	            }
32	            results.print(JSON.writeValueAsString(output));
33	        } catch (IOException e) {
34	            throw new UncheckedIOException(e);
35	        }
36	    }
37	
38	    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
39	        List<InsuredItem> items = new ArrayList<>();
40	        for (JsonNode item : quoteStep.get("items")) {
41	            items.add(new InsuredItem(item.get("type").asText(),
42	                    item.path("cursed").asBoolean(false),
43	                    item.path("enchantment").asInt(0)));
44	        }
45	        return items;
46	    }
47	}
