1	import java.math.BigDecimal;
2	import java.util.LinkedHashMap;
3	import java.util.List;
4	import java.util.Map;
5	import java.util.Set;
6	
7	/**
8	 * The MHPCO price list: what the office charges as base premium for the items a
9	 * policy covers. Main items are priced individually; every component costs the
10	 * same per-component rate whichever type it is, and a building block of alike
11	 * components is offered at a special rate.
12	 *
13	 * The per-component rate ignores the component's type, but the block rate does
14	 * not: a block is a quantity of <em>alike</em> components, so the tariff also
15	 * decides which items count as alike (see {@link #alikenessGroupOf}) and groups
16	 * them before pricing.
17	 *
18	 * This is the office's tariff. It changes on its own schedule, independently of
19	 * the modifier rules in {@link PremiumPolicy}.
20	 */
21	public class PriceList {
22	
23	    private static final Map<String, BigDecimal> MAIN_ITEM_BASE_PREMIUM = Map.of(
24	            "sword", new BigDecimal("100"),
25	            "amulet", new BigDecimal("60"),
26	            "staff", new BigDecimal("80"),
27	            "potion", new BigDecimal("40"));
28	
29	    /** Components are all priced at one rate per component, whatever their type. */
30	    private static final BigDecimal COMPONENT_BASE_PREMIUM = new BigDecimal("25");
31	
32	    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");
33	
34	    /** A building block of exactly 3 alike components is offered at this rate. */
35	    private static final BigDecimal COMPONENT_BLOCK_BASE_PREMIUM = new BigDecimal("60");
36	    private static final int COMPONENT_BLOCK_SIZE = 3;
37	
38	    /** The base premium for all items a policy covers, alike items priced together. */
39	    public BigDecimal policyBasePremium(List<InsuredItem> insuredItems) {
40	        BigDecimal total = BigDecimal.ZERO;
41	        for (Map.Entry<String, Integer> alikeItems : groupedByAlikeness(insuredItems).entrySet()) {
42	            total = total.add(basePremium(alikeItems.getKey(), alikeItems.getValue()));
43	        }
44	        return total;
45	    }
46	
47	    /**
48	     * The base premium of one insured item on its own, which is what an
49	     * item-specific surcharge such as the curse surcharge is charged on. A
50	     * component priced within a block is not charged on its own.
51	     */
52	    public BigDecimal basePremium(InsuredItem insuredItem) {
53	        return basePremium(insuredItem.type(), 1);
54	    }
55	
56	    private static Map<String, Integer> groupedByAlikeness(List<InsuredItem> insuredItems) {
57	        Map<String, Integer> counts = new LinkedHashMap<>();
58	        for (InsuredItem insuredItem : insuredItems) {
59	            counts.merge(alikenessGroupOf(insuredItem.type()), 1, Integer::sum);
60	        }
61	        return counts;
62	    }
63	
64	    /**
65	     * The office counts two items as alike when they are of exactly the same
66	     * type, not merely of the same family: 2 runes and a moonstone are three
67	     * loose components priced at 75 G, never a block, because a moonstone is not
68	     * a rune. Widening "alike" to a family (rune-y, gemstone-y) would mean
69	     * returning a family name here instead of the type itself.
70	     */
71	    private static String alikenessGroupOf(String itemType) {
72	        return itemType;
73	    }
74	
75	    private static BigDecimal basePremium(String itemType, int count) {
76	        if (COMPONENT_TYPES.contains(itemType)) {
77	            return componentsBasePremium(count);
78	        }
79	        return MAIN_ITEM_BASE_PREMIUM.get(itemType).multiply(BigDecimal.valueOf(count));
80	    }
81	
82	    private static BigDecimal componentsBasePremium(int count) {
83	        if (qualifiesForBlockRate(count)) {
84	            return COMPONENT_BLOCK_BASE_PREMIUM;
85	        }
86	        return COMPONENT_BASE_PREMIUM.multiply(BigDecimal.valueOf(count));
87	    }
88	
89	    /**
90	     * The office grants the block rate only to a holding of exactly 3 alike
91	     * components. It neither prices a part of a block at the block rate (4
92	     * components are not a block) nor breaks a larger holding down into blocks
93	     * (7 components are priced as 7, not as two blocks and one loose component).
94	     */
95	    private static boolean qualifiesForBlockRate(int alikeComponentCount) {
96	        return alikeComponentCount == COMPONENT_BLOCK_SIZE;
97	    }
98	}
